#include <stdint.h>
#include <string.h>
#include NVIM_BASE64_C

// Equivalence proof for tool patch 'pad_last' (generated by tool_patches.py).
void harness(void) {
  // The condition reads only one char of src, so covering every value of that
  // char (both signs) covers every call. No assumptions.
  char src[2];
  const size_t src_len = 2;
  int before = (src_len >= 1 && src[src_len - 1] == '=');
  int after = (src_len >= 1 && ((const uint8_t *)src)[src_len - 1] == '=');
  __CPROVER_assert(before == after, "pad_last: rewrite equals original");
}
